import React, { useState } from 'react';

import Header from './Header';
import Cart from './Cart';
import productData from './productData'
import Footer from './Footer';

let data = (val) => {

    function rate() {
        if (val.productRating === 1) {
            return `⭐`;
        }
        else if (val.productRating === 2) {
            return `⭐ ⭐`;
        }
        else if (val.productRating === 3) {
            return `⭐ ⭐ ⭐ `;
        }
        else if (val.productRating === 4) {
            return `⭐ ⭐ ⭐ ⭐`;
        }
        else if (val.productRating === 5) {
            return `⭐ ⭐ ⭐ ⭐ ⭐`;
        }

    }

    return (
        <Cart
            productImage={val.productImage}
            productName={val.productName}
            productCategory={val.productCategory}
            productPrice={val.productPrice}
            oldPrice={val.oldPrice}
            productInfo={val.productInfo}
            productRating={rate()}
        />

    );

}

let App = () => {
    const [name, setName] = useState('');

    return (
        <>
            <Header />

            <div style={{ margin: '20px', padding: '10px', border: '1px solid #ddd' }}>
                <h3>Input / Output Example</h3>
                <input
                    type="text"
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    placeholder="Type your name"
                    style={{ padding: '8px', marginRight: '10px' }}
                />
                <p>
                    Output: <strong>{name || 'Your name will appear here'}</strong>
                </p>
            </div>

            <div>
                {productData.map(data)}
            </div>
            {/* <Footer /> */}

        </>
    );
}

export default App;
